+  len = snprintf(status, sizeof(status),
+                 "{\"board\":\"ESP32-P4X-Function-EV-Board\","
+                 "\"product\":\"VelaPoka\",\"bsp\":1,"
+                 "\"capabilities\":\"0x%08lx\","
+                 "\"ready\":\"0x%08lx\","
