+  if (len < 0)
+    {
+      return -EIO;
+    }
+
+  if (filep->f_pos >= len)
+    {
+      return 0;
+    }
+
+  available = (size_t)len - filep->f_pos;
+  count = buflen < available ? buflen : available;
+  memcpy(buffer, status + filep->f_pos, count);
+  filep->f_pos += count;
+  return count;
